//! A reader for the one JSON shape this build script consumes.
//!
//! The file is a two-level object of objects whose leaves are a string or `null`, generated by a
//! machine and never edited by hand. A general parser would be more code than the shape is worth,
//! so this one accepts exactly that shape and refuses everything else: an unexpected token is a
//! hard error, because a silently half-read table would become a parity denominator that is
//! quietly too small.

/// One entry of the inner object: a property name and the preference gating it.
pub(crate) struct Entry {
    /// The property name, spelled as a style sheet spells it.
    pub(crate) name: String,
    /// The preference that has to be on for the property to be usable, if there is one.
    pub(crate) pref: Option<String>,
}

/// Everything the generated property list says.
pub(crate) struct Catalog {
    /// The longhands, in the order the file lists them.
    pub(crate) longhands: Vec<Entry>,
    /// The shorthands, likewise.
    pub(crate) shorthands: Vec<Entry>,
}

/// Reads the generated property list.
///
/// # Errors
///
/// Returns a message naming the byte offset when the text is not the expected shape.
pub(crate) fn parse(text: &str) -> Result<Catalog, String> {
    let mut reader = Reader {
        bytes: text.as_bytes(),
        at: 0,
    };
    let mut longhands = None;
    let mut shorthands = None;
    reader.expect(b'{')?;
    loop {
        let section = reader.string()?;
        reader.expect(b':')?;
        let entries = reader.section()?;
        match section.as_str() {
            "longhands" => longhands = Some(entries),
            "shorthands" => shorthands = Some(entries),
            other => return Err(format!("unexpected section `{other}`")),
        }
        if !reader.comma()? {
            break;
        }
    }
    reader.expect(b'}')?;
    match (longhands, shorthands) {
        (Some(longhands), Some(shorthands)) => Ok(Catalog {
            longhands,
            shorthands,
        }),
        _ => Err("the file names neither `longhands` nor `shorthands`".to_owned()),
    }
}

/// A cursor over the text.
struct Reader<'a> {
    /// The whole file.
    bytes: &'a [u8],
    /// Where reading has got to.
    at: usize,
}

impl Reader<'_> {
    /// Skips whitespace and returns the next byte without consuming it.
    fn peek(&mut self) -> Result<u8, String> {
        while self.bytes.get(self.at).is_some_and(u8::is_ascii_whitespace) {
            self.at += 1;
        }
        self.bytes
            .get(self.at)
            .copied()
            .ok_or_else(|| format!("the text ends at byte {}", self.at))
    }

    /// Consumes one expected byte.
    fn expect(&mut self, wanted: u8) -> Result<(), String> {
        let found = self.peek()?;
        if found != wanted {
            return Err(format!(
                "expected `{}` at byte {}, found `{}`",
                wanted as char, self.at, found as char
            ));
        }
        self.at += 1;
        Ok(())
    }

    /// Consumes a separating comma, answering whether there was one.
    fn comma(&mut self) -> Result<bool, String> {
        if self.peek()? == b',' {
            self.at += 1;
            return Ok(true);
        }
        Ok(false)
    }

    /// Reads one double-quoted string, which in this file never carries an escape.
    fn string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let start = self.at;
        while self.bytes.get(self.at).is_some_and(|byte| *byte != b'"') {
            if self.bytes[self.at] == b'\\' {
                return Err(format!(
                    "an escape at byte {}, which this reader refuses to guess at",
                    self.at
                ));
            }
            self.at += 1;
        }
        let text = String::from_utf8(self.bytes[start..self.at].to_vec())
            .map_err(|error| format!("byte {start} begins invalid UTF-8: {error}"))?;
        self.expect(b'"')?;
        Ok(text)
    }

    /// Reads one `{ "name": { "pref": … }, … }` section.
    fn section(&mut self) -> Result<Vec<Entry>, String> {
        let mut entries = Vec::new();
        self.expect(b'{')?;
        if self.peek()? == b'}' {
            self.at += 1;
            return Ok(entries);
        }
        loop {
            let name = self.string()?;
            self.expect(b':')?;
            entries.push(Entry {
                name,
                pref: self.body()?,
            });
            if !self.comma()? {
                break;
            }
        }
        self.expect(b'}')?;
        Ok(entries)
    }

    /// Reads one property's `{ "pref": null | "name" }` body.
    fn body(&mut self) -> Result<Option<String>, String> {
        let mut pref = None;
        self.expect(b'{')?;
        if self.peek()? == b'}' {
            self.at += 1;
            return Ok(pref);
        }
        loop {
            let field = self.string()?;
            self.expect(b':')?;
            let value = if self.peek()? == b'"' {
                Some(self.string()?)
            } else {
                self.null()?;
                None
            };
            if field == "pref" {
                pref = value;
            }
            if !self.comma()? {
                break;
            }
        }
        self.expect(b'}')?;
        Ok(pref)
    }

    /// Consumes the literal `null`.
    fn null(&mut self) -> Result<(), String> {
        for wanted in b"null" {
            self.expect(*wanted)?;
        }
        Ok(())
    }
}
